const config = $('Set AISIX Probe Config').first().json;
const response = $input.first().json;
const statusCode = Number(response.statusCode ?? 0);
const body = response.body ?? {};

if (statusCode < 200 || statusCode >= 300) {
  return [{ json: { workflow_path: 'discovery_failure', overall_status: 'attention', stage: 'model_discovery', status_code: statusCode || null, error_type: body?.error?.type ?? 'model_discovery_failed', reason: 'AISIX did not return a usable model list.' } }];
}

const maxModels = Math.max(1, Math.min(Number(config.max_models) || 10, 50));
const aliases = Array.isArray(body.data)
  ? body.data.map((item) => item?.id).filter((id) => typeof id === 'string' && id.length > 0).slice(0, maxModels)
  : [];

if (aliases.length === 0) {
  return [{ json: { workflow_path: 'discovery_failure', overall_status: 'attention', stage: 'model_discovery', status_code: statusCode, error_type: 'no_visible_models', reason: 'The caller key can access no concrete model aliases.' } }];
}

return aliases.map((modelAlias) => ({
  json: {
    workflow_path: 'probe',
    aisix_base_url: config.aisix_base_url,
    probe_prompt: config.probe_prompt,
    model_alias: modelAlias,
    probe_started_at: new Date().toISOString(),
  },
}));

const response = $json;
const source = $('Build Model Probe Queue').item.json;
const statusCode = Number(response.statusCode ?? 0);
const headers = response.headers ?? {};
const body = response.body ?? {};
const header = (name) => headers[name] ?? headers[name.toLowerCase()] ?? headers[name.toUpperCase()] ?? null;
const content = body?.choices?.[0]?.message?.content;
const latencyMs = Math.max(0, Date.now() - Date.parse(source.probe_started_at));

let probeStatus = 'unhealthy';
if (statusCode >= 200 && statusCode < 300 && typeof content === 'string' && content.length > 0) probeStatus = 'healthy';
else if (statusCode === 429) probeStatus = 'rate_limited';
else if (statusCode === 422) probeStatus = 'policy_blocked';
else if (statusCode === 401 || statusCode === 403) probeStatus = 'auth_failed';

return { json: {
  model_alias: source.model_alias,
  probe_status: probeStatus,
  status_code: statusCode || null,
  latency_ms: latencyMs,
  retry_after_seconds: header('retry-after'),
  aisix_request_id: header('x-aisix-request-id'),
  error_type: body?.error?.type ?? null,
} };

const checks = $input.all().map((item) => item.json);
const counts = checks.reduce((acc, check) => {
  acc[check.probe_status] = (acc[check.probe_status] ?? 0) + 1;
  return acc;
}, {});
const needsAttention = checks.some((check) => check.probe_status !== 'healthy');

return [{ json: {
  overall_status: needsAttention ? 'attention' : 'healthy',
  checked_at: new Date().toISOString(),
  summary: { total: checks.length, ...counts },
  checks,
} }];
